import type { AuthContext, Env, WorkspaceResponse } from '../../types.js';
import { parseCheckpointCreateRequest } from '../checkpoint-jobs.js';
import type { ParsedCheckpointCreateRequest } from '../checkpoint-jobs.js';
import {
  appendWorkspaceEvent,
  createWorkspace,
  generateWorkspaceId,
  getWorkspace,
  markWorkspaceFailed,
} from '../../lib/db.js';
import { hydrateWorkspaceToReady, WorkspaceReadyTransitionError } from './ready.js';
import { jsonResponse } from './shared.js';
import {
  buildWorkspaceCreateFallback,
  sourceBundleR2Key,
  uploadWorkspaceSourceBundle,
} from './source-bundle.js';

export async function handleCreateWorkspace(request: Request, env: Env, authContext?: AuthContext): Promise<Response> {
  if (!env.SOURCE_BUNDLES) {
    return jsonResponse({ error: 'SOURCE_BUNDLES R2 binding is not configured' }, 500);
  }

  let parsed: ParsedCheckpointCreateRequest;
  try {
    parsed = await parseCheckpointCreateRequest(request);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    return jsonResponse({ error: message }, 400);
  }

  const workspaceId = generateWorkspaceId();
  const sandboxId = `workspace-${workspaceId}`;
  const sourceBundleKey = sourceBundleR2Key(workspaceId, parsed.metadata.source.commitSha);
  let bundleUploaded = false;
  let workspaceCreated = false;
  let workspaceReadyPersisted = false;
  let baselineReady = true;

  try {
    await uploadWorkspaceSourceBundle(env, sourceBundleKey, parsed);
    bundleUploaded = true;

    await createWorkspace(env.DB, {
      id: workspaceId,
      sourceType: parsed.metadata.source.type,
      checkpointId: parsed.metadata.source.checkpointId,
      commitSha: parsed.metadata.source.commitSha,
      sourceRef: parsed.metadata.source.ref,
      sourceProjectRoot: parsed.metadata.source.projectRoot,
      sourceBundleKey,
      sourceBundleSha256: parsed.bundleSha256,
      sourceBundleBytes: parsed.bundleBytes,
      sandboxId,
      accountId: authContext?.isHostedMode ? authContext.accountId : null,
    });
    workspaceCreated = true;

    await appendWorkspaceEvent(env.DB, {
      workspaceId,
      eventType: 'workspace_created',
      payload: {
        checkpointId: parsed.metadata.source.checkpointId,
        commitSha: parsed.metadata.source.commitSha,
        sourceRef: parsed.metadata.source.ref ?? null,
      },
    });

    ({ baselineReady } = await hydrateWorkspaceToReady(env, workspaceId, sandboxId, parsed.bundleArrayBuffer));
    workspaceReadyPersisted = true;

    await appendWorkspaceEvent(env.DB, {
      workspaceId,
      eventType: 'workspace_ready',
      payload: {
        baselineReady,
      },
    });

    const workspace = await getWorkspace(env.DB, workspaceId);
    if (!workspace) {
      return jsonResponse({ error: 'Workspace created but could not be loaded' }, 500);
    }

    return jsonResponse({ workspace }, 201);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);

    if (error instanceof WorkspaceReadyTransitionError) {
      return jsonResponse({ error: error.message }, 409);
    }

    if (workspaceReadyPersisted) {
      try {
        const workspace = await getWorkspace(env.DB, workspaceId);
        if (workspace) {
          return jsonResponse({ workspace }, 201);
        }
      } catch {
        // Best-effort readback only.
      }

      const workspace: WorkspaceResponse = buildWorkspaceCreateFallback({
        workspaceId,
        sourceType: parsed.metadata.source.type,
        checkpointId: parsed.metadata.source.checkpointId,
        commitSha: parsed.metadata.source.commitSha,
        sourceRef: parsed.metadata.source.ref,
        sourceProjectRoot: parsed.metadata.source.projectRoot,
        sourceBundleKey,
        sourceBundleSha256: parsed.bundleSha256,
        sourceBundleBytes: parsed.bundleBytes,
        sandboxId,
        baselineReady,
      });

      return jsonResponse(
        {
          workspace,
          warning: `Workspace became ready but post-ready bookkeeping failed: ${message}`,
        },
        201
      );
    }

    if (workspaceCreated) {
      try {
        await markWorkspaceFailed(env.DB, workspaceId, message, 'workspace_create_failed');
        await appendWorkspaceEvent(env.DB, {
          workspaceId,
          eventType: 'workspace_failed',
          payload: { message },
        });
      } catch {
        // Best-effort only.
      }
    }

    if (bundleUploaded && !workspaceCreated) {
      try {
        await env.SOURCE_BUNDLES.delete(sourceBundleKey);
      } catch {
        // Best-effort cleanup.
      }
    }

    return jsonResponse({ error: `Failed to create workspace: ${message}` }, 500);
  }
}

import * as p from '@clack/prompts';
import { approveReviewPolicy, createReview, deriveReviewPolicy } from '../../clients/worker/reviews.js';
import { getWorkerUrl } from '../../clients/worker/shared.js';
import { validateReviewCochangeTokenReadiness } from '../../commands/review/preflight.js';
import { startReviewStudioCommand } from './open.js';
import { buildIdempotencyKey, buildStudioReviewRoutePath, resolveReviewGitProvenance } from './create-shared.js';

export async function createReviewCommand(
  workspaceId: string,
  deploymentId: string,
  options?: {
    idempotencyKey?: string;
    policyMode?: 'none' | 'auto' | 'review';
    reviewBasis?: 'checkpoint' | 'environment';
    openStudio?: boolean;
    openStudioPort?: number;
    severityThreshold?: 'low' | 'medium' | 'high' | 'critical';
    maxFindings?: number;
    model?: string;
    intentSummaryModel?: string;
    includeProvenance?: boolean;
    includeValidationEvidence?: boolean;
  }
): Promise<void> {
  const workerUrl = getWorkerUrl();
  if (!workerUrl) {
    throw new Error('NIMBUS_WORKER_URL environment variable is required');
  }

  await validateReviewCochangeTokenReadiness();
  const policyMode = options?.policyMode ?? 'none';
  const reviewBasis = options?.reviewBasis ?? 'checkpoint';

  const gitProvenance = resolveReviewGitProvenance();

  const provenance = {
    repo: gitProvenance.repo,
    branch: gitProvenance.branch,
    ...(options?.intentSummaryModel?.trim() ? { intentSummaryModel: options.intentSummaryModel.trim() } : {}),
  };

  let reviewId = '';
  let status = '';
  let resultUrl = '';
  let eventsUrl = '';
  if (policyMode === 'none') {
    const response = await createReview(workerUrl, options?.idempotencyKey?.trim() || buildIdempotencyKey(workspaceId, deploymentId), {
      target: {
        type: 'workspace_deployment',
        workspaceId,
        deploymentId,
      },
      mode: 'report_only',
      policyMode,
      reviewBasis,
      policy: {
        severityThreshold: options?.severityThreshold ?? 'low',
        maxFindings: options?.maxFindings,
        includeProvenance: options?.includeProvenance ?? true,
        includeValidationEvidence: options?.includeValidationEvidence ?? true,
      },
      model: options?.model,
      provenance,
    });
    reviewId = response.reviewId;
    status = response.status;
    resultUrl = response.resultUrl;
    eventsUrl = response.eventsUrl;
  } else {
    const derived = await deriveReviewPolicy(workerUrl, {
      workspaceId,
      deploymentId,
      policyMode,
      reviewBasis,
      provenance,
    });
    reviewId = derived.reviewId;
    if (policyMode === 'auto') {
      await approveReviewPolicy(workerUrl, reviewId, {
        approvedPolicy: derived.derivedPolicy,
      });
      status = 'policy_approved';
    } else {
      status = derived.status;
    }
    resultUrl = `${workerUrl}/api/reviews/${encodeURIComponent(reviewId)}`;
    eventsUrl = `${workerUrl}/api/reviews/${encodeURIComponent(reviewId)}/events`;
  }

  p.log.success(`Review queued: ${reviewId}`);
  p.log.message(`Policy mode: ${policyMode}`);
  p.log.message(`Review basis: ${reviewBasis}`);
  p.log.message(`Status: ${status}`);
  p.log.message(`Result URL: ${resultUrl}`);
  p.log.message(`Events URL: ${eventsUrl}`);

  if (options?.openStudio) {
    await startReviewStudioCommand({
      port: options.openStudioPort,
      routePath: buildStudioReviewRoutePath({
        reviewId,
        route: 'reports',
        repo: gitProvenance.repo,
        branch: gitProvenance.branch,
      }),
      detach: true,
    });
  }
}

