function deriveSessionPhase(status: ReviewRunStatus | null): ReviewSessionPhase {
  switch (status) {
    case 'policy_pending':
    case 'policy_ready':
      return 'waiting_on_human';
    case 'running':
      return 'reviewing';
    case 'succeeded':
      return 'completed';
    case 'failed':
