}

async function loadLatestReviewUnlessManuallyFailed(env: Env, reviewId: string): Promise<ReviewRunResponse | null> {
  const latest = await getReviewRun(env.DB, reviewId);
  return isManuallyFailedReview(latest) ? null : latest;
}

function startManualFailAbortMonitor(env: Env, reviewId: string): { signal: AbortSignal; stop: () => void } {
  const controller = new AbortController();
  let stopped = false;
  let polling = false;
  let timer: ReturnType<typeof setInterval> | null = null;

  const stop = (): void => {
    if (stopped) {
      return;
    }
    stopped = true;
    if (timer !== null) {
      clearInterval(timer);
      timer = null;
    }
  };

  const poll = async (): Promise<void> => {
    if (stopped || polling || controller.signal.aborted) {
      return;
    }
    polling = true;
    try {
      const latest = await getReviewRun(env.DB, reviewId);
      if (isManuallyFailedReview(latest)) {
        controller.abort();
        stop();
      }
    } catch {
      // Best-effort polling only; transient read failures must not become unhandled rejections.
    } finally {
      polling = false;
    }
  };

  timer = setInterval(() => {
    void poll();
  }, 250);
  void poll();

  return { signal: controller.signal, stop };
}

/**
 * Claims, executes, persists, and finalizes one review run.
 * This is the main orchestration boundary for review execution and retry scheduling.
 */
export async function processReviewRun(env: Env, reviewId: string, options?: ReviewRunExecutionOptions): Promise<void> {
  const claimed = await claimReviewRunForExecution(env.DB, reviewId);
  if (!claimed) {
    const existing = await getReviewRun(env.DB, reviewId);
    if (existing?.status === 'running') {
      await handleUnclaimedReviewRun(env, reviewId, existing, options?.allowRetryScheduling ?? true);
    }
    return;
  }

  let review: ReviewRunResponse | null = null;
  const manualFailAbortMonitor = startManualFailAbortMonitor(env, reviewId);
  try {
    review = await getReviewRun(env.DB, reviewId);
    if (!review) {
      return;
    }

    const payload = await getReviewRunRequestPayload(env.DB, reviewId);
    if (!payload) {
      await updateReviewRunStatus(env.DB, reviewId, 'failed', {
        errorCode: 'review_not_found',
        errorMessage: 'Review request payload no longer exists',
      });
      await appendReviewEvent(env.DB, {
        reviewId,
        eventType: 'review_failed',
        payload: {
          code: 'review_not_found',
          message: 'Review request payload no longer exists',
        },
      });
      return;
    }

    const reviewContext = await assembleReviewContextBootstrap(env, review, payload, options);
    const report = await executeReviewRun(env, review, payload, reviewContext, {
      ...options,
      abortSignal: manualFailAbortMonitor.signal,
    });
    const latest = await loadLatestReviewUnlessManuallyFailed(env, reviewId);
    if (!latest) {
      return;
    }
    await finalizeSuccessfulReview(env, reviewId, payload, report, {
      expectedAttemptCount: review.attemptCount,
      allowRetryScheduling: options?.allowRetryScheduling,
    });
  } catch (error) {
    const message = formatReviewAnalysisError(error, {
      openrouterApiKey: readOptionalString(options?.openrouterApiKey),
    });
    const latest = await loadLatestReviewUnlessManuallyFailed(env, reviewId);
    if (!latest) {
      return;
    }
    const attemptCount = review?.attemptCount ?? latest?.attemptCount ?? 0;

    const allowRetryScheduling = options?.allowRetryScheduling !== false;
    if (allowRetryScheduling && shouldRetryReviewError(error) && attemptCount <= 2) {
      const retryScheduled = await scheduleReviewRetryIfCurrent(env, reviewId, {
        attemptCount,
        message,
        reason: message.slice(0, 500),
      });
      if (retryScheduled) {
        throw new QueueRetryError('Review transient failure; retry requested');
      }
    }

    const contextAssemblyErrorCode = error instanceof ReviewContextAssemblyError ? error.code : null;
    const finalErrorCode = contextAssemblyErrorCode ?? 'review_execution_failed';
    await finalizeFailedReviewIfCurrent(env, reviewId, {
      errorCode: finalErrorCode,
      message,
      contextAssemblyErrorCode,
      expectedAttemptCount: attemptCount,
    });
  } finally {
    manualFailAbortMonitor.stop();
  }
}

/**
 * Repeats inline review execution while the persisted state requests another retry cycle.
 */
export async function runReviewInlineWithRetries(
  env: Env,
  reviewId: string,
  maxCycles = 4,
  options?: ReviewRunExecutionOptions
): Promise<void> {
  for (let cycle = 0; cycle < maxCycles; cycle += 1) {
    try {
      await processReviewRun(env, reviewId, options);
    } catch {
      // Retry scheduling is inferred from persisted status.
    }

    const latest = await getReviewRun(env.DB, reviewId);
    if (!latest) {
      return;
    }
    if (latest.status !== 'queued') {
      return;
    }
    if (latest.error?.code !== 'retry_scheduled') {
      return;
    }
  }

  await finalizeInlineRetryExhaustion(env, reviewId);
}

import type { Env, ReviewContext, ReviewRunResponse } from '../../../types.js';
import { appendReviewEvent, getWorkspaceDeployment, getWorkspaceDeploymentRequestPayload } from '../../db.js';
import { runWorkspaceDeploymentAgentAnalysis } from '../../review-analysis.js';
import { asRecord, readOptionalString, resolveReviewAnalysisModel } from '../context-helpers.js';
import { loadAuthoritativeDeploymentDiff } from '../context-diff.js';
import { buildEvidence, buildHeuristicFindings } from '../report.js';
import type { ReviewRunExecutionOptions } from '../shared.js';
import { DEFAULT_REVIEW_ANALYSIS_TIMEOUT_MS, parseTimeoutMs, withTimeout } from './shared.js';

/**
 * Runs the optional model-backed analysis pass and returns agent output plus heuristic inputs.
 */
export async function runDeploymentReviewAnalysisStage(
  env: Env,
  review: ReviewRunResponse,
  payload: Record<string, unknown>,
  reviewContext: ReviewContext,
  inputs: {
    requestValidation: Record<string, unknown>;
    resultProvenance: Record<string, unknown>;
    resultArtifact: Record<string, unknown>;
    intentSessionContext: string[];
    derivedIntentSummary: unknown;
    promptGoal: string;
    promptConstraints: string[];
    promptDecisions: string[];
  },
  options?: ReviewRunExecutionOptions
) {
  const deployment = await getWorkspaceDeployment(env.DB, review.workspaceId, review.deploymentId);
  if (!deployment) {
    throw new Error(`Deployment not found for review target ${review.deploymentId}`);
  }

  const deploymentRequest = (await getWorkspaceDeploymentRequestPayload(env.DB, review.deploymentId)) ?? {};
  const deploymentEvents = await import('../../db.js').then((m) => m.listWorkspaceDeploymentEvents(env.DB, review.workspaceId, review.deploymentId, 0, 500));
  const heuristicFindings = buildHeuristicFindings(review, deploymentEvents);
  const analysisEvidence = buildEvidence(deploymentEvents, deployment, inputs.resultArtifact, true);
  const provenanceOperationId = typeof inputs.resultProvenance.operationId === 'string' ? inputs.resultProvenance.operationId : null;
  const reviewDiffArtifactId = typeof inputs.resultArtifact.reviewDiffArtifactId === 'string'
    ? inputs.resultArtifact.reviewDiffArtifactId
    : typeof inputs.resultProvenance.reviewDiffArtifactId === 'string'
      ? inputs.resultProvenance.reviewDiffArtifactId
      : null;
  const authoritativeDiff = await loadAuthoritativeDeploymentDiff(env, review.workspaceId, provenanceOperationId, reviewDiffArtifactId);
  const reviewAnalysisModel = resolveReviewAnalysisModel(payload, env);
  let agentAnalysis: Awaited<ReturnType<typeof runWorkspaceDeploymentAgentAnalysis>> = null;
  const requestOpenrouterApiKey = readOptionalString(options?.openrouterApiKey);
  const reviewAgentEnabled = Boolean((env.AGENT_SDK_URL ?? '').trim()) || Boolean((requestOpenrouterApiKey ?? env.OPENROUTER_API_KEY ?? '').trim());
  const reviewAnalysisProvider = (requestOpenrouterApiKey ?? env.OPENROUTER_API_KEY ?? '').trim() ? 'openrouter' : 'cloudflare_agents_sdk';
  const deploymentSourceBundleKey =
    typeof inputs.resultArtifact.sourceBundleKey === 'string' && inputs.resultArtifact.sourceBundleKey.trim()
      ? inputs.resultArtifact.sourceBundleKey.trim()
      : deployment.sourceBundleKey ?? null;

  if (reviewAgentEnabled && deploymentSourceBundleKey) {
    await appendReviewEvent(env.DB, {
      reviewId: review.id,
      eventType: 'review_analysis_agent_started',
      payload: { provider: reviewAnalysisProvider, model: reviewAnalysisModel },
    });

    const analysisTimeoutMs = parseTimeoutMs(env.REVIEW_ANALYSIS_TIMEOUT_MS, DEFAULT_REVIEW_ANALYSIS_TIMEOUT_MS);
    try {
      agentAnalysis = await withTimeout(
        runWorkspaceDeploymentAgentAnalysis(env, {
          reviewId: review.id,
          workspaceId: review.workspaceId,
          deploymentId: review.deploymentId,
          deploymentSandboxId: `review-snapshot-${review.id}`,
          sourceBundleKey: deploymentSourceBundleKey,
          modelOverride: reviewAnalysisModel,
          authoritativeDiffSnapshot: authoritativeDiff
            ? { source: authoritativeDiff.source, artifactId: authoritativeDiff.artifactId, patch: authoritativeDiff.patch }
            : undefined,
          goal: inputs.promptGoal,
          constraints: inputs.promptConstraints,
          decisions: inputs.promptDecisions.filter(Boolean),
          intentSessionContext: inputs.intentSessionContext,
          intentSummary: inputs.derivedIntentSummary as never,
          evidenceCatalog: analysisEvidence.map((item) => ({ id: item.id, type: item.type, label: item.label, status: item.status })),
          deploymentSummary: {
            provider: deployment.provider,
            deployedUrl: deployment.deployedUrl,
            validationSummary: JSON.stringify(inputs.requestValidation),
          },
          abortSignal: options?.abortSignal,
          reviewContext,
          rootListing: {},
          diffSnapshot: {},
            onLifecycleEvent: async (eventType, eventPayload) => {
              await appendReviewEvent(env.DB, {
                reviewId: review.id,
                eventType,
                payload: eventPayload,
              });
            },
            openrouterApiKey: requestOpenrouterApiKey,
          }),
        analysisTimeoutMs,
        () => new Error(`Review analysis timed out after ${analysisTimeoutMs}ms while waiting for model/provider response`)
      );
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      if (/timed out|timeout/i.test(message)) {
        await appendReviewEvent(env.DB, {
          reviewId: review.id,
          eventType: 'review_analysis_timeout',
          payload: { timeoutMs: analysisTimeoutMs, message },
        });
      }
      throw error;
    }

    if (!agentAnalysis) {
      throw new Error('Review analysis did not produce output.');
    }
    if (agentAnalysis.validation.fallbackApplied) {
      throw new Error(`Review analysis produced non-authoritative fallback output (${agentAnalysis.validation.fallbackReason ?? 'unknown'}).`);
    }

    await appendReviewEvent(env.DB, {
      reviewId: review.id,
      eventType: 'review_analysis_agent_completed',
      payload: {
        provider: agentAnalysis.provider,
        model: agentAnalysis.model,
        stepsExecuted: agentAnalysis.stepsExecuted,
        findingCount: agentAnalysis.findings.length,
      },
    });
  }

  if (reviewAgentEnabled && !deploymentSourceBundleKey) {
    throw new Error('Deployment snapshot unavailable; review analysis cannot proceed without source bundle.');
  }
  if (reviewAgentEnabled && !agentAnalysis) {
    throw new Error('Review analysis did not produce output.');
  }

  return { deployment, deploymentRequest, deploymentEvents, heuristicFindings, analysisEvidence, agentAnalysis };
}

import type { Env, ReviewContext, ReviewReport, ReviewRunResponse, ReviewSeverity } from '../../types.js';
import { getWorkspaceDeployment } from '../db.js';
import { readOptionalString, asRecord } from './context-helpers.js';
import type { ReviewRunExecutionOptions } from './shared.js';
import { runDeploymentReviewAnalysisStage } from './deployment-report/analysis.js';
import { buildDeploymentReportOutput } from './deployment-report/output.js';
import { buildDeploymentReportInputs } from './deployment-report/provenance.js';
import { REVIEW_SEVERITY_RANK } from './deployment-report/shared.js';

/**
 * Builds the final review report for a successful workspace deployment, including agent analysis,
 * heuristic findings, evidence, intent, and provenance metadata.
 */
export async function buildWorkspaceDeploymentReport(
  env: Env,
  review: ReviewRunResponse,
  payload: Record<string, unknown>,
  reviewContext: ReviewContext,
  options?: ReviewRunExecutionOptions
): Promise<ReviewReport> {
  const deployment = await getWorkspaceDeployment(env.DB, review.workspaceId, review.deploymentId);
  if (!deployment) {
    throw new Error(`Deployment not found for review target ${review.deploymentId}`);
  }
  const result = asRecord(deployment.result);
  const inputs = await buildDeploymentReportInputs(
    env,
    review,
    payload,
    (await import('../db.js').then((m) => m.getWorkspaceDeploymentRequestPayload(env.DB, review.deploymentId))) ?? {},
    result,
    reviewContext.retrieval.coChange.filesConsidered,
    readOptionalString(options?.openrouterApiKey)
  );
  const analysisStage = await runDeploymentReviewAnalysisStage(env, review, payload, reviewContext, {
    requestValidation: inputs.requestValidation,
    resultProvenance: inputs.resultProvenance,
    resultArtifact: inputs.resultArtifact,
    intentSessionContext: inputs.intentSessionContext,
    derivedIntentSummary: inputs.derivedIntentSummary,
    promptGoal: inputs.promptGoal,
    promptConstraints: inputs.promptConstraints,
    promptDecisions: inputs.promptDecisions,
  }, options);
  const { deploymentEvents, heuristicFindings, analysisEvidence, agentAnalysis } = analysisStage;

  return buildDeploymentReportOutput({
    review,
    reviewContext,
    findingsFromAnalysis: agentAnalysis?.findings ?? [],
    heuristicFindings,
    severityThreshold: inputs.severityThreshold,
    maxFindings: inputs.maxFindings,
    deployment,
    resultArtifact: inputs.resultArtifact,
    includeValidationEvidence: inputs.includeValidationEvidence,
    includeMarkdownSummary: inputs.includeMarkdownSummary,
    includeProvenance: inputs.includeProvenance,
    derivedIntentSummary: inputs.derivedIntentSummary,
    promptGoal: inputs.promptGoal,
    promptConstraints: inputs.promptConstraints,
    promptDecisions: inputs.promptDecisions,
    requestProvenance: inputs.requestProvenance,
    provenanceRepo: inputs.provenanceRepo,
    provenanceBranch: inputs.provenanceBranch,
    policyItems: inputs.policyItems,
    rawSessionPrompts: inputs.rawSessionPrompts,
    promptSummary: inputs.promptSummary,
    transcriptUrl: inputs.transcriptUrl,
    contextResolutionMode: inputs.contextResolutionMode,
    contextResolutionOriginalCheckpointId: inputs.contextResolutionOriginalCheckpointId,
    contextResolutionResolvedCheckpointId: inputs.contextResolutionResolvedCheckpointId,
    contextResolutionResolvedCommitSha: inputs.contextResolutionResolvedCommitSha,
    contextResolutionResolvedCommitMessage: inputs.contextResolutionResolvedCommitMessage,
    advisories: inputs.advisories,
    agentAnalysis,
    deploymentEvents,
  });
}

