         id,
         workspace_id,
         deployment_id,
         session_id,
         target_type,
         mode,
         status,
         idempotency_key,
         request_payload_json,
         request_payload_sha256,
         account_id,
         provenance_json,
         repo,
         branch,
         derived_policy_json,
         approved_policy_json,
         approved_policy_sha256,
         created_at,
         updated_at
       )
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
       RETURNING *`
    )
    .bind(
      input.id,
      input.workspaceId,
