            totalBytesIncluded: input.reviewContext.stats.totalBytesIncluded,
            estimatedTokens: input.reviewContext.stats.estimatedTokens,
            tokenBudget: input.reviewContext.stats.tokenBudget,
          },
          reviewedFiles: {
